import React from 'react';
import { Building2, ShieldCheck } from 'lucide-react';

export type DocumentType = 'TAX_INVOICE' | 'QUOTATION' | 'SALES_ORDER' | 'PURCHASE_ORDER' | 'PURCHASE_BILL';

export interface PartyDetails {
  name: string;
  companyName?: string;
  address?: string;
  city?: string;
  state?: string;
  pincode?: string;
  gstin?: string;
  pan?: string;
  cin?: string;
  email?: string;
  phone?: string;
}

export interface DocumentLineItem {
  id?: string;
  name: string;
  hsnSac?: string;
  quantity: number;
  rate: number;
  discount?: number;
  taxRate?: number;
  taxAmount?: number;
  total: number;
}

export interface UniversalDocumentData {
  documentType: DocumentType;
  documentNumber: string;
  date: string;
  dueDate?: string;
  status?: string;
  placeOfSupply?: string;
  supplyType?: string; // e.g. "Intra-State (CGST + SGST)" or "Inter-State (IGST)"
  reverseCharge?: 'Yes' | 'No';
  orderRef?: string;
  paymentMode?: string;
  paymentStatus?: string;
  seller: PartyDetails;
  buyer: PartyDetails;
  items: DocumentLineItem[];
  subtotal: number;
  cgstAmount?: number;
  sgstAmount?: number;
  igstAmount?: number;
  discount?: number;
  grandTotal: number;
  amountInWords?: string;
  taxNote?: string;
  terms?: string[];
  bankDetails?: {
    bankName?: string;
    accountName?: string;
    accountNumber?: string;
    ifsc?: string;
  };
}

export const getDocumentTitles = (type: DocumentType) => {
  switch (type) {
    case 'QUOTATION':
      return { header: 'QUOTATION / ESTIMATE', sub: 'Commercial Quotation' };
    case 'SALES_ORDER':
      return { header: 'SALES ORDER', sub: 'Original Order Confirmation' };
    case 'PURCHASE_ORDER':
      return { header: 'PURCHASE ORDER', sub: 'Vendor Purchase Requisition' };
    case 'PURCHASE_BILL':
      return { header: 'PURCHASE BILL / INWARD', sub: 'Tax Inward Receipt' };
    case 'TAX_INVOICE':
    default:
      return { header: 'TAX INVOICE / RECEIPT', sub: 'Original for Recipient' };
  }
};

export const UniversalDocumentTemplate: React.FC<{
  data: UniversalDocumentData;
  className?: string;
  id?: string;
}> = ({ data, className = '', id = 'universal-printable-area' }) => {
  const titles = getDocumentTitles(data.documentType);
  const isPurchase = data.documentType === 'PURCHASE_BILL' || data.documentType === 'PURCHASE_ORDER';

  return (
    <div
      id={id}
      className={`bg-white p-6 sm:p-10 text-slate-800 text-xs leading-relaxed font-sans ${className}`}
      style={{ minHeight: '297mm', boxSizing: 'border-box' }}
    >
      {/* 1. Header Section */}
      <div className="flex flex-col sm:flex-row justify-between items-start gap-6 border-b-2 border-slate-900 pb-6">
        <div>
          <div className="flex items-center gap-2">
            <span className="grid place-items-center h-8 w-8 rounded-xl bg-violet-700 text-white font-black text-sm">
              {data.seller.companyName?.charAt(0) || data.seller.name?.charAt(0) || 'A'}
            </span>
            <span className="text-2xl font-black tracking-tight text-slate-900">
              {data.seller.companyName || data.seller.name}
            </span>
          </div>
          <p className="mt-1 text-[13px] font-extrabold text-slate-900">
            {data.seller.companyName}
          </p>
          <p className="mt-0.5 text-[11px] text-slate-600 max-w-sm">
            {data.seller.address}
          </p>
          <div className="mt-1.5 flex flex-wrap gap-x-4 gap-y-0.5 text-[10px] text-slate-500 font-medium">
            {data.seller.gstin && (
              <span><strong className="text-slate-700">GSTIN:</strong> {data.seller.gstin}</span>
            )}
            {data.seller.pan && (
              <span><strong className="text-slate-700">PAN:</strong> {data.seller.pan}</span>
            )}
            {data.seller.cin && (
              <span><strong className="text-slate-700">CIN:</strong> {data.seller.cin}</span>
            )}
          </div>
          <p className="mt-0.5 text-[10px] text-slate-500">
            {data.seller.email && (
              <>Support: <span className="font-medium text-slate-700">{data.seller.email}</span></>
            )}
            {data.seller.phone && (
              <> | Phone: <span className="font-medium text-slate-700">{data.seller.phone}</span></>
            )}
          </p>
        </div>

        {/* Document Meta Heading */}
        <div className="text-left sm:text-right shrink-0">
          <div className="inline-block rounded-md bg-slate-100 border border-slate-300 px-3 py-1 text-center">
            <span className="text-[11px] font-black uppercase tracking-wider text-slate-900">
              {titles.header}
            </span>
            <p className="text-[9px] font-semibold text-violet-700">
              {titles.sub}
            </p>
          </div>

          <div className="mt-3 space-y-1 font-mono text-[11px]">
            <p>
              <span className="text-slate-500 font-sans">Number:</span>{' '}
              <strong className="text-slate-900 text-xs">{data.documentNumber}</strong>
            </p>
            <p>
              <span className="text-slate-500 font-sans">Date:</span>{' '}
              <span className="text-slate-900 font-semibold">{data.date}</span>
            </p>
            {data.dueDate && (
              <p>
                <span className="text-slate-500 font-sans">Due Date:</span>{' '}
                <span className="text-slate-900 font-semibold">{data.dueDate}</span>
              </p>
            )}
            <p>
              <span className="text-slate-500 font-sans">Place of Supply:</span>{' '}
              <span className="text-slate-900 font-semibold">{data.placeOfSupply || 'Uttar Pradesh (09)'}</span>
            </p>
            <p>
              <span className="text-slate-500 font-sans">Supply Type:</span>{' '}
              <span className="text-slate-900 font-semibold">{data.supplyType || 'Intra-State (CGST + SGST)'}</span>
            </p>
            <p>
              <span className="text-slate-500 font-sans">Reverse Charge:</span>{' '}
              <span className="text-slate-900 font-semibold">{data.reverseCharge || 'No'}</span>
            </p>
          </div>
        </div>
      </div>

      {/* 2. Billed Details & Fulfillment Row */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 my-6 p-4 rounded-xl bg-slate-50/70 border border-slate-200/80">
        <div>
          <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400 mb-1.5 flex items-center gap-1">
            <Building2 className="h-3 w-3 text-slate-400" />
            {isPurchase ? 'BILLED BY (SUPPLIER DETAILS)' : 'BILLED TO (CUSTOMER DETAILS)'}
          </p>
          <p className="text-sm font-extrabold text-slate-900">
            {data.buyer.companyName || data.buyer.name}
          </p>
          {data.buyer.gstin && (
            <div className="mt-1 flex items-center gap-1.5">
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-violet-50 border border-violet-200 text-[10px] font-mono font-bold text-violet-800">
                GSTIN: {data.buyer.gstin}
              </span>
              {data.buyer.pan && (
                <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-slate-100 text-[10px] font-mono font-medium text-slate-700">
                  PAN: {data.buyer.pan}
                </span>
              )}
            </div>
          )}
          <p className="text-slate-600 text-[11px] mt-1">{data.buyer.email || '—'}</p>
          {data.buyer.phone && <p className="text-slate-600 text-[11px]">{data.buyer.phone}</p>}
          {data.buyer.address && (
            <p className="text-slate-600 text-[11px] mt-1">
              {[data.buyer.address, data.buyer.city, data.buyer.state, data.buyer.pincode].filter(Boolean).join(', ')}
            </p>
          )}
        </div>

        {/* Payment & Fulfillment Side */}
        <div className="sm:border-l sm:border-slate-200 sm:pl-6 space-y-1 text-[11px]">
          <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400 mb-1.5 flex items-center gap-1">
            <ShieldCheck className="h-3 w-3 text-slate-400" /> Payment &amp; Terms
          </p>
          {data.orderRef && (
            <p className="flex justify-between sm:justify-start sm:gap-4">
              <span className="text-slate-500 w-28">Ref No:</span>
              <strong className="font-mono text-slate-900 font-semibold">{data.orderRef}</strong>
            </p>
          )}
          <p className="flex justify-between sm:justify-start sm:gap-4">
            <span className="text-slate-500 w-28">Payment Mode:</span>
            <span className="text-slate-900 font-semibold">{data.paymentMode || 'Bank / UPI / Credit'}</span>
          </p>
          {data.bankDetails?.bankName && !isPurchase && (
            <div className="pt-1 text-[10px] space-y-0.5 border-t border-slate-200 mt-2">
              <p className="text-slate-500 font-bold uppercase">Bank Account Details:</p>
              <p><span className="text-slate-500">Bank:</span> {data.bankDetails.bankName}</p>
              <p><span className="text-slate-500">A/C:</span> {data.bankDetails.accountNumber}</p>
              <p><span className="text-slate-500">IFSC:</span> {data.bankDetails.ifsc}</p>
            </div>
          )}
        </div>
      </div>

      {/* 3. Line Items Table */}
      <div className="overflow-x-auto rounded-xl border border-slate-200 mb-6">
        <table className="w-full text-left text-xs border-collapse">
          <thead>
            <tr className="bg-slate-100/80 border-b border-slate-200 text-[10px] font-bold uppercase tracking-wider text-slate-600">
              <th className="px-3 py-2.5 w-10 text-center">#</th>
              <th className="px-3 py-2.5">Item Description</th>
              <th className="px-3 py-2.5 w-24 text-center">HSN/SAC</th>
              <th className="px-3 py-2.5 w-14 text-center">Qty</th>
              <th className="px-3 py-2.5 w-24 text-right">Unit Rate (₹)</th>
              <th className="px-3 py-2.5 w-20 text-center">Tax (GST)</th>
              <th className="px-3 py-2.5 w-28 text-right">Total (₹)</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {data.items.map((item, idx) => (
              <tr key={item.id ?? idx} className="hover:bg-slate-50/40">
                <td className="px-3 py-3 text-center font-mono text-[11px] text-slate-400">{idx + 1}</td>
                <td className="px-3 py-3">
                  <p className="font-bold text-slate-900">{item.name}</p>
                </td>
                <td className="px-3 py-3 text-center font-mono text-[11px] text-slate-500">{item.hsnSac || '—'}</td>
                <td className="px-3 py-3 text-center font-mono font-semibold text-slate-700">{item.quantity}</td>
                <td className="px-3 py-3 text-right font-mono text-slate-700">₹{item.rate.toFixed(2)}</td>
                <td className="px-3 py-3 text-center text-[10px] font-semibold text-slate-500">{item.taxRate ? `${item.taxRate}%` : '0%'}</td>
                <td className="px-3 py-3 text-right font-mono font-bold text-slate-900">₹{item.total.toFixed(2)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* 4. Financial Totals & In-Words */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-2 pb-6 border-b border-slate-200">
        <div className="flex flex-col justify-between space-y-4">
          <div className="rounded-xl bg-slate-50 p-3.5 border border-slate-200/70">
            <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400 mb-1">
              Amount Chargeable (in words)
            </p>
            <p className="text-xs font-extrabold text-slate-900 italic">
              {data.amountInWords || 'Indian Rupees Only'}
            </p>
          </div>
          {data.taxNote && (
            <div className="text-[10px] text-slate-500 space-y-1">
              <p className="font-semibold text-slate-700">Tax Note:</p>
              <p>{data.taxNote}</p>
            </div>
          )}
        </div>

        <div className="space-y-2 font-mono text-xs">
          <div className="flex justify-between py-1 text-slate-600">
            <span className="font-sans">Subtotal (Taxable Value):</span>
            <span>₹{data.subtotal.toFixed(2)}</span>
          </div>
          {data.cgstAmount !== undefined && (
            <div className="flex justify-between py-1 text-slate-500">
              <span className="font-sans">Central GST (CGST):</span>
              <span>₹{data.cgstAmount.toFixed(2)}</span>
            </div>
          )}
          {data.sgstAmount !== undefined && (
            <div className="flex justify-between py-1 text-slate-500">
              <span className="font-sans">State GST (SGST):</span>
              <span>₹{data.sgstAmount.toFixed(2)}</span>
            </div>
          )}
          {data.igstAmount !== undefined && (
            <div className="flex justify-between py-1 text-slate-500">
              <span className="font-sans">Integrated GST (IGST):</span>
              <span>₹{data.igstAmount.toFixed(2)}</span>
            </div>
          )}
          {data.discount ? (
            <div className="flex justify-between py-1 text-emerald-600 font-semibold">
              <span className="font-sans">Discount:</span>
              <span>- ₹{data.discount.toFixed(2)}</span>
            </div>
          ) : null}
          <div className="flex justify-between items-center rounded-xl bg-violet-50/70 border border-violet-200 p-3 font-sans mt-3">
            <span className="text-sm font-black text-violet-950">Grand Total (INR):</span>
            <span className="text-base font-black font-mono text-violet-900">
              ₹{data.grandTotal.toFixed(2)}
            </span>
          </div>
        </div>
      </div>

      {/* 5. Footer & Signatory */}
      <div className="flex flex-col sm:flex-row justify-between items-end gap-6 pt-6">
        <div className="text-[10px] text-slate-500 space-y-1 max-w-md">
          <p className="font-bold text-slate-700">Terms &amp; Conditions:</p>
          <ul className="list-disc pl-4 space-y-0.5">
            {data.terms?.map((term, i) => <li key={i}>{term}</li>) || (
              <>
                <li>Goods once sold will not be taken back or exchanged.</li>
                <li>Redemption / delivery is subject to agreed operational timelines.</li>
                <li>This is a computer-generated document and requires no physical signature.</li>
              </>
            )}
          </ul>
        </div>

        <div className="text-center sm:text-right shrink-0">
          <div className="inline-block rounded-xl border border-dashed border-slate-300 p-3 bg-slate-50/50 text-center min-w-[200px]">
            <p className="text-[9px] font-bold uppercase tracking-wider text-slate-400">
              For {data.seller.companyName}
            </p>
            <div className="my-2 flex items-center justify-center gap-1 text-emerald-700">
              <ShieldCheck className="h-4 w-4" />
              <span className="text-[10px] font-black uppercase tracking-wider">
                DIGITALLY AUTHORIZED
              </span>
            </div>
            <p className="border-t border-slate-200 pt-1 text-[10px] font-bold text-slate-800">
              Authorized Signatory
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

Kindly do complete document styling overhaul across the entire AccountX platform.

OBJECTIVE:
Standardize the print preview, modal view, and generated PDF layout for ALL documents:
1. Sales Invoices
2. Quotations / Estimates
3. Sales Orders
4. Purchase Bills
5. Purchase Orders

REFERENCE INSPIRATION:
Adopt the modern, clean, GST-compliant structure from the GyftKart Tax Invoice layout (attached in project as reference):
- 2-Column Clean Header with bold company name, CIN, GSTIN, PAN, and stylized doc-type pill.
- Billed To / Details Container: Light slate background card (`bg-slate-50/70 border border-slate-200`) separating Billed Party from Payment/Fulfillment info.
- Line Items Table: Clean bordered table with uppercase headers (#, Item Description, HSN/SAC, Qty, Unit Rate, Tax %, Total).
- Totals Grid: Amount chargeable in words (italicized) on the left, line-by-line Subtotal, CGST, SGST/IGST, and highlighted Grand Total pill on the right.
- Footer: Terms & conditions bullet points on left, "DIGITALLY AUTHORIZED" dashed signatory box on right.


1. Create a centralized reusable template component: `src/components/documents/UniversalDocumentTemplate.tsx`.
2. Support all 5 document types (`TAX_INVOICE`, `QUOTATION`, `SALES_ORDER`, `PURCHASE_BILL`, `PURCHASE_ORDER`) by dynamically swapping:
   - Header title & badge labels
   - Party roles (For Sales/Quotations: Seller = our business, Buyer = Customer; For Purchase: Seller = Supplier, Buyer = our business)
   - Bank details (displayed on Sales/Quotations, hidden or customized on Purchase Bills)
3. Update all existing view/print/modal components (`SaleInvoicePrint.tsx`, `QuotationPrint.tsx`, `PurchaseBillPrint.tsx`, and their respective Modals) to render this unified template.
4. Integrate isolated iframe printing matching `OrderInvoiceModal.tsx` so printing produces clean 1-page A4 output with proper background colors and no clipped margins.
5. Run `npm run build` and ensure zero TypeScript or build errors.
